"""API-Definition EduKSX-Staffing – Ressourcen aus dem Datenmodell, Fachaktionen und berechnete Schemas (deutsch beschrieben)."""

O = "/api/v1/org"


def R(tabelle, schema, op, op_mehrzahl, einzahl, mehrzahl, **kw):
    return {"tabelle": tabelle, "schema": schema, "op": op, "op_mehrzahl": op_mehrzahl, "einzahl": einzahl, "mehrzahl": mehrzahl,
            "pfad": f"{O}/{tabelle.replace('_', '-')}", **kw}


JAHR = ["school_id", "school_year_id"]

API = {
    "titel": "EduKSX-Staffing",
    "beschreibung": "Einsatzplanung: Stellenplan und VZE nach den Vorgaben des Kantons Zürich, Klassen und Unterricht, Pensen und "
                    "Berufsauftrag, Ressourcen, Freigaben und Anstellung, Pensenumfrage, Stellvertretungen, Gespräche und "
                    "Personaldossier, Tagesstrukturen. Berechnete Werte (VZE, Ist-Pensum, Saldo, Prüfregeln) liefert die API.",
    "tags": {
        "planning-parameters": "Kantonale und kommunale Parameter", "staffing-plans": "Stellenplan und VZE",
        "subjects": "Fächer", "lesson-tables": "Lektionentafeln", "staff-members": "Personen und Pensen",
        "classes": "Klassen und Klassenlehrpersonen", "assignments": "Unterricht und Einsätze", "job-duties": "Berufsauftrag",
        "resources": "Ressourcen", "releases": "Freigaben und Anstellung", "workload-surveys": "Pensenumfrage",
        "absences": "Stellvertretungen", "mid-year-changes": "Mutationen", "staff-reviews": "Personalgespräche",
        "dossier-entries": "Personaldossier", "care-offerings": "Tagesstrukturen", "deadlines": "Jahresablauf und Fristen",
        "checks": "Prüfregeln und Auswertungen", "exports": "Exporte",
    },
    "ressourcen": [
        R("planning_parameters", "PlanningParameter", "PlanningParameter", "PlanningParameters", "Parameter", "Parameter", filter=["school_year_id"], ops="lcru",
          eingebettet={"age_bands": ("list:ref:PlanningParameterAgeBand", "Netto-Jahresarbeitszeit nach Alter", "Altersstufen mit Stunden und Ferientagen")}),
        R("staffing_plans", "StaffingPlan", "StaffingPlan", "StaffingPlans", "Stellenplan", "Stellenpläne", filter=JAHR, ops="lcru", artikel="einen",
          nur_lesen=["status", "is_budget_locked", "is_care_released"],
          eingebettet={"coordinations": ("list:ref:StaffingPlanCoordination", "Koordination", "Koordination Sekundarschule je Person")}),
        R("subjects", "Subject", "Subject", "Subjects", "Fach", "Fächer", artikel="ein"),
        R("lesson_tables", "LessonTable", "LessonTable", "LessonTables", "Lektionentafel", "Lektionentafeln", filter=["school_year_id"], artikel="eine",
          eingebettet={"subjects": ("list:ref:LessonTableSubject", "Fächer der Tafel", "Wochenlektionen und Halbklassen je Fach")}),
        R("staff_members", "StaffMember", "StaffMember", "StaffMembers", "Person in der Planung", "Personen in der Planung", filter=JAHR + ["staff_type", "q"], artikel="eine",
          berechnet={"display_name": ("text", "Name", "aus der Personenreferenz"), "short_name": ("text?", "Kürzel", "aus der Personenreferenz"),
                     "age_on_reference_day": ("int?", "Alter am Stichtag", "aus Geburtsdatum und Stichjahr"),
                     "subject_ids": ("list:uuid", "Fächer", "Unterrichtsberechtigung")}),
        R("classes", "Class", "Class", "Classes", "Klasse", "Klassen", filter=JAHR, artikel="eine",
          eingebettet={"class_teachers": ("list:ref:ClassTeacher", "Klassenlehrpersonen", "mit Stundenanteil; leer = gleichmässig")},
          berechnet={"student_lessons_target": ("decimal", "WL Schüler/innen (Soll)", "aus der Lektionentafel"),
                     "teacher_lessons_target": ("decimal", "WL Lehrpersonen (Soll)", "inkl. Halbklassen"),
                     "teacher_lessons_allocated": ("decimal", "WL Lehrpersonen (zugeteilt)", "Summe der Zuteilungen"),
                     "size_status": ("enum:ok=in Ordnung;limit=an der Höchstzahl;over=über der Höchstzahl", "Klassengrösse", "Prüfung gegen die Höchstzahl")}),
        R("resources", "Resource", "Resource", "Resources", "Ressource", "Ressourcen", filter=JAHR, artikel="eine",
          berechnet={"demand": ("decimal", "Bedarf", "aus den Gefässen"), "allocated": ("decimal", "Verplant", "Summe der Zuteilungen"),
                     "balance": ("decimal", "Saldo", "Budget minus verplant"), "items": ("list:text", "Posten", "Zuteilungen als Text")}),
        R("assignments", "Assignment", "Assignment", "Assignments", "Gefäss", "Gefässe", filter=JAHR + ["assignment_group", "class_id"],
          eingebettet={"allocations": ("list:ref:AssignmentAllocation", "Zuteilung", "Personen mit Menge in der Einheit des Gefässes")},
          berechnet={"target_amount": ("decimal", "Soll", "Lehrpersonen-Soll inkl. Halbklassen"), "open_amount": ("decimal", "Offen", "Soll minus zugeteilt"),
                     "employment_label": ("text", "Anstellungstyp", "kantonal, kommunal oder weitere aus der Ressource")}),
        R("job_duties", "JobDuty", "JobDuty", "JobDuties", "Gefäss des Berufsauftrags", "Gefässe des Berufsauftrags", filter=JAHR + ["area"],
          eingebettet={"participants": ("list:ref:JobDutyParticipant", "Teilnehmende", "mit abweichenden Stunden")}),
        R("releases", "Release", "Release", "Releases", "Freigabe", "Freigaben", filter=["status"], ops="lr", artikel="eine",
          berechnet={"is_changed_since_release": ("bool", "Geändert seit Freigabe", "Vergleich Abbild ↔ aktueller Stand"),
                     "current": ("ref:WorkloadSnapshot", "Aktueller Stand", "Pensum jetzt")}),
        R("workload_surveys", "WorkloadSurvey", "WorkloadSurvey", "WorkloadSurveys", "Pensenumfrage", "Pensenumfragen", filter=["status"], ops="lru",
          nur_lesen=["status", "invited_at", "reminded_at", "submitted_at"], artikel="eine"),
        R("absences", "Absence", "Absence", "Absences", "Ausfall", "Ausfälle", filter=["status", "valid_from"], artikel="einen",
          eingebettet={"reports": ("list:ref:AbsenceReport", "Rapport", "gehaltene Lektionen je Tag")}),
        R("mid_year_changes", "MidYearChange", "MidYearChange", "MidYearChanges", "Mutation", "Mutationen", filter=["status"], artikel="eine"),
        R("staff_reviews", "StaffReview", "StaffReview", "StaffReviews", "Gespräch", "Gespräche", filter=["user_id"]),
        R("dossier_entries", "DossierEntry", "DossierEntry", "DossierEntries", "Dossiereintrag", "Dossiereinträge", filter=["user_id", "dossier_category_id"], artikel="einen"),
        R("care_offerings", "CareOffering", "CareOffering", "CareOfferings", "Betreuungsangebot", "Betreuungsangebote", filter=JAHR,
          berechnet={"staff_needed": ("decimal", "Bedarf Betreuungspersonen", "Kinder ÷ Betreuungsschlüssel, mindestens Mindestbesetzung")}),
        R("deadlines", "Deadline", "Deadline", "Deadlines", "Frist", "Fristen", filter=["school_year_id"], artikel="eine"),
    ],
    "schemas": {
        "PlanningParameterAgeBand": {"title": "Altersstufe", "description": "Netto-Jahresarbeitszeit und Ferientage bis zu einem Alter",
                                     "felder": {"maximum_age": ("int", "Alter bis", "Altersstufe"), "net_hours": ("decimal", "Netto-Jahresarbeitszeit", "Stunden bei 100 %"),
                                                "vacation_days": ("int", "Ferientage", "Anspruch")}, "pflicht": ["maximum_age", "net_hours", "vacation_days"]},
        "StaffingPlanCoordination": {"title": "Koordination", "description": "Koordination Sekundarschule einer Person",
                                     "felder": {"user_id": ("uuid", "Person", "koordinierende Person"), "fte": ("decimal", "VZE", "Anteil Koordination")}, "pflicht": ["user_id", "fte"]},
        "LessonTableSubject": {"title": "Fach der Lektionentafel", "description": "Wochenlektionen eines Fachs in der Tafel",
                               "felder": {"subject_id": ("uuid", "Fach", "Verweis auf das Fach"), "weekly_lessons": ("decimal", "Wochenlektionen", "Soll der Schüler/innen"),
                                          "is_half_class": ("bool", "Halbklassen", "verdoppelt die Lehrpersonen-Lektionen")}, "pflicht": ["subject_id", "weekly_lessons"]},
        "ClassTeacher": {"title": "Klassenlehrperson", "description": "Klassenlehrperson mit Stundenanteil",
                         "felder": {"staff_member_id": ("uuid", "Klassenlehrperson", "Person in der Planung"), "hours": ("decimal?", "Stundenanteil", "leer = gleichmässig aufteilen")},
                         "pflicht": ["staff_member_id"]},
        "AssignmentAllocation": {"title": "Zuteilung", "description": "Zuteilung eines Gefässes an eine Person",
                                 "felder": {"staff_member_id": ("uuid", "Person", "Person in der Planung"), "amount": ("decimal", "Menge", "in der Einheit des Gefässes")},
                                 "pflicht": ["staff_member_id", "amount"]},
        "JobDutyParticipant": {"title": "Teilnahme", "description": "Teilnahme an einem Gefäss des Berufsauftrags",
                               "felder": {"staff_member_id": ("uuid", "Person", "Person in der Planung"), "hours_override": ("decimal?", "Abweichende Stunden", "Entlastung bzw. individuelle Stunden"),
                                          "hours": ("decimal!", "Stunden", "nach Regel berechnet")}, "pflicht": ["staff_member_id"]},
        "AbsenceReport": {"title": "Rapport", "description": "gehaltene Vikariatslektionen eines Tages",
                          "felder": {"held_on": ("date", "Datum", "Tag der Vertretung"), "lessons": ("decimal", "Lektionen", "gehaltene Lektionen")}, "pflicht": ["held_on", "lessons"]},
        "WorkloadSnapshot": {"title": "Pensum (Stand)", "description": "Pensum einer Person zu einem Zeitpunkt; bei der Freigabe eingefroren",
                             "felder": {"weekly_lessons": ("decimal", "Wochenlektionen", "Summe der Lektionen"), "hours": ("decimal", "Stunden", "Jahresstunden"),
                                        "workload_percent": ("decimal", "Beschäftigungsgrad", "berechnet in %"), "items": ("list:text", "Posten", "Zuteilungen als Text")}},
        "StaffingPlanCalculation": {"title": "Stellenplan (berechnet)", "description": "VZE nach der Weisung VZE mit Rechnungsweg",
                                    "felder": {"teaching_fte": ("decimal", "VZE Berufsauftrag", "Schülerzahl × Sozialindex × Korrekturfaktor ÷ Basiswert ÷ 100"),
                                               "principal_fte": ("decimal", "VZE Schulleitung", "Sockel plus Anteil je VZE"), "design_pool_lessons": ("decimal", "Gestaltungspool (WL)", "Anteil je VZE"),
                                               "coordination_fte": ("decimal", "Koordination (VZE)", "Anteil je VZE Sek"), "therapy_fte": ("decimal", "Therapie (VZE)", "aus dem Stellenplan"),
                                               "gsl_lessons": ("decimal", "DaZ (WL)", "Aufnahmeunterricht ausserhalb der VZE"), "total_fte": ("decimal", "VZE gesamt", "Summe"),
                                               "steps": ("list:text", "Rechnungsweg", "Formeln mit eingesetzten Werten und Rechtsgrundlage")}},
        "Workload": {"title": "Pensum", "description": "Soll und Ist einer Person mit Prüfregeln (berechnet)",
                     "felder": {"staff_member_id": ("uuid", "Person", "Person in der Planung"), "agreed_workload_percent": ("decimal?", "Vereinbarter Beschäftigungsgrad", "Soll"),
                                "calculated_workload_percent": ("decimal", "Berechneter Beschäftigungsgrad", "Ist aus den Zuteilungen"),
                                "difference_hours": ("decimal", "Differenz (Stunden)", "Ist minus Soll"), "teaching_lessons": ("decimal", "Unterricht (WL)", "Summe der Lektionen"),
                                "class_teacher_hours": ("decimal", "Klassenlehrperson (Stunden)", "aus den Klassen"), "allowance_hours": ("decimal", "Pauschalen (Stunden)", "Berufsauftrag"),
                                "additional_hours": ("decimal", "Zusätzlich (Stunden)", "Ämter und Zusatzgefässe"), "items": ("list:text", "Posten", "Zuteilungen als Text"),
                                "findings": ("list:ref:CheckFinding", "Hinweise", "verletzte Prüfregeln")}},
        "CheckFinding": {"title": "Prüfhinweis", "description": "Ergebnis einer Prüfregel",
                         "felder": {"rule": ("text", "Regel", "Kurzname der Prüfregel"), "severity": ("enum:info=Hinweis;warning=Warnung;error=Fehler", "Stufe", "Gewicht des Befunds"),
                                    "message": ("text", "Meldung", "Text für Menschen"), "legal_basis": ("text?", "Rechtsgrundlage", "z. B. «LPVO § 10»"), "subject_id": ("uuid?", "Bezug", "betroffenes Objekt")}},
        "ReleaseRequest": {"title": "Freigabe", "description": "Freigabe des Pensums einer Person",
                           "felder": {"remark": ("text?", "Bemerkung", "Freitext der Schulleitung")}},
        "BulkReleaseRequest": {"title": "Sammelfreigabe", "description": "mehrere abgeschlossene Planungen freigeben",
                               "felder": {"staff_member_ids": ("list:uuid", "Personen", "Personen in der Planung")}, "pflicht": ["staff_member_ids"]},
        "EmploymentRequest": {"title": "Anstellung", "description": "Anstellung durch die Schulverwaltung erledigt",
                              "felder": {"administration_note": ("text?", "Rückmeldung Schulverwaltung", "Freitext")}},
        "ReleaseComparison": {"title": "Vergleich", "description": "Stand bei Freigabe gegen aktuellen Stand",
                              "felder": {"released": ("ref:WorkloadSnapshot", "Stand bei Freigabe", "Abbild"), "current": ("ref:WorkloadSnapshot", "Aktueller Stand", "Pensum jetzt"),
                                         "differences": ("list:text", "Unterschiede", "geänderte Posten")}},
        "BudgetLock": {"title": "Budgetsperre", "description": "Ressourcen sperren oder entsperren",
                       "felder": {"is_budget_locked": ("bool", "Budget gesperrt", "Sperre der Schulverwaltung")}, "pflicht": ["is_budget_locked"]},
        "SurveyInvitation": {"title": "Einladung zur Pensenumfrage", "description": "Personen einladen oder erinnern",
                             "felder": {"school_year_id": ("uuid", "Schuljahr", "Umfrage für dieses Schuljahr"), "staff_member_ids": ("list:uuid", "Personen", "leer = alle"),
                                        "is_reminder": ("bool", "Erinnerung", "nur erinnern"), "due_on": ("date?", "Frist", "Abgabe bis")}, "pflicht": ["school_year_id"]},
        "Matrix": {"title": "Klasse – Fach – Lehrperson", "description": "wer unterrichtet was in welcher Klasse (berechnet)",
                   "felder": {"classes": ("list:text", "Klassen", "Spalten"), "subjects": ("list:text", "Fächer", "Zeilen"),
                              "cells": ("list:object", "Zellen", "Klasse, Fach, Kürzel, Klassenlehrperson eigene/andere"), "differences": ("list:object", "Differenz", "zugeteilt minus benötigt je Klasse")}},
        "PlanningEvent": {"title": "Verlaufseintrag", "description": "Eintrag im Verlauf der Planung",
                          "felder": {"occurred_at": ("datetime", "Zeitpunkt", "wann"), "actor_role": ("text", "Rolle", "Rolle beim Auslösen"), "text": ("text", "Eintrag", "Beschreibung des Vorgangs")}},
        "ReleaseEvent": {"title": "Ereignis Freigabe", "description": "Pensum freigegeben, Anstellung erledigt oder Freigabe geändert",
                         "felder": {"release_id": ("uuid", "Freigabe", "Verweis"), "staff_member_id": ("uuid", "Person in der Planung", "Verweis"),
                                    "user_id": ("uuid", "Person", "Personenreferenz"), "status": ("enum:released=freigegeben;employed=angestellt;completed=erledigt;withdrawn=zurückgezogen", "Status", "Stand der Freigabe"),
                                    "snapshot": ("ref:WorkloadSnapshot", "Pensum", "eingefrorener Stand")}},
    },
    "aktionen": [
        {"pfad": f"{O}/staffing-plans/{{id}}/calculation", "methode": "get", "op": "getStaffingPlanCalculation", "summary": "Stellenplan berechnen",
         "beschreibung": "VZE nach der Weisung VZE mit Rechnungsweg und Rechtsgrundlage.", "antwort": "StaffingPlanCalculation", "fehler": ("401", "403", "404")},
        {"pfad": f"{O}/staffing-plans/{{id}}/budget-lock", "op": "setBudgetLock", "summary": "Budget sperren oder entsperren", "recht": "admin", "body": "BudgetLock",
         "antwort": "StaffingPlan", "ifmatch": True, "zweck": "Sperre der Ressourcen durch die Schulverwaltung"},
        {"pfad": f"{O}/staffing-plans/{{id}}/report", "op": "reportStaffingPlan", "summary": "Stellenplan an den Kanton melden", "recht": "admin", "antwort": "StaffingPlan", "ifmatch": True},
        {"pfad": f"{O}/staff-members/{{id}}/workload", "methode": "get", "op": "getWorkload", "summary": "Pensum mit Prüfregeln", "antwort": "Workload", "fehler": ("401", "403", "404")},
        {"pfad": f"{O}/workloads", "methode": "get", "op": "listWorkloads", "summary": "Pensen aller Personen", "ressource": "staff-members",
         "query": [("school_id", "uuid", "Schule", "Planung je Schule"), ("school_year_id", "uuid", "Schuljahr", "Planung je Schuljahr"), ("only_differences", "bool", "Nur Abweichungen", "nur Personen mit Differenz")],
         "antwort": "liste:Workload", "fehler": ("401", "403", "422")},
        {"pfad": f"{O}/checks", "methode": "get", "op": "listCheckFindings", "summary": "Prüfregeln der Planung auswerten",
         "query": [("school_id", "uuid", "Schule", "Planung je Schule"), ("school_year_id", "uuid", "Schuljahr", "Planung je Schuljahr")], "antwort": "liste:CheckFinding", "fehler": ("401", "403", "422")},
        {"pfad": f"{O}/matrix", "methode": "get", "op": "getMatrix", "summary": "Matrix Klasse – Fach – Lehrperson", "ressource": "classes",
         "query": [("school_id", "uuid", "Schule", "Planung je Schule"), ("school_year_id", "uuid", "Schuljahr", "Planung je Schuljahr")], "antwort": "Matrix", "fehler": ("401", "403", "422")},
        {"pfad": f"{O}/staff-members/{{id}}/release", "op": "releaseWorkload", "summary": "Pensum freigeben", "beschreibung": "Friert den Stand ein (Abbild) und meldet die Freigabe.",
         "ressource": "releases", "body": "ReleaseRequest", "antwort": "Release", "code": "201"},
        {"pfad": f"{O}/releases/bulk", "op": "releaseWorkloads", "summary": "Sammelfreigabe", "ressource": "releases", "body": "BulkReleaseRequest", "antwort": "liste:Release", "code": "201"},
        {"pfad": f"{O}/releases/{{id}}/employment", "op": "completeEmployment", "summary": "Anstellung erledigt", "recht": "admin", "body": "EmploymentRequest", "antwort": "Release", "ifmatch": True},
        {"pfad": f"{O}/releases/{{id}}/withdrawal", "op": "withdrawRelease", "summary": "Freigabe zurückziehen", "antwort": "Release", "ifmatch": True},
        {"pfad": f"{O}/releases/{{id}}/comparison", "methode": "get", "op": "compareRelease", "summary": "Stand bei Freigabe mit aktuellem Stand vergleichen", "antwort": "ReleaseComparison", "fehler": ("401", "403", "404")},
        {"pfad": f"{O}/planning-events", "methode": "get", "op": "listPlanningEvents", "summary": "Verlauf der Planung", "ressource": "releases",
         "query": [("school_id", "uuid", "Schule", "Planung je Schule")], "antwort": "liste:PlanningEvent", "fehler": ("401", "403", "422")},
        {"pfad": f"{O}/workload-surveys/invitations", "op": "inviteWorkloadSurveys", "summary": "Zur Pensenumfrage einladen oder erinnern", "body": "SurveyInvitation", "antwort": "liste:WorkloadSurvey"},
        {"pfad": "/api/v1/me/workload-survey", "methode": "get", "op": "getMyWorkloadSurvey", "summary": "Eigene Pensenumfrage lesen", "ressource": "workload-surveys",
         "antwort": "WorkloadSurvey", "klassen": ["personal"], "fehler": ("401", "403", "404")},
        {"pfad": "/api/v1/me/workload-survey/submission", "op": "submitMyWorkloadSurvey", "summary": "Eigene Pensenumfrage einreichen", "ressource": "workload-surveys",
         "antwort": "WorkloadSurvey", "klassen": ["personal"], "ifmatch": True},
        {"pfad": f"{O}/absences/{{id}}/reports", "op": "createAbsenceReport", "summary": "Gehaltene Lektionen eines Tages erfassen", "body": "AbsenceReport", "antwort": "Absence", "code": "201"},
        {"pfad": f"{O}/absences/{{id}}/report-to-canton", "op": "reportAbsence", "summary": "Vikariat an den Kanton melden", "recht": "admin", "antwort": "Absence", "ifmatch": True},
        {"pfad": f"{O}/exports/vze-tool", "op": "fillVzeTool", "summary": "VZE-Tool des Volksschulamts befüllen", "ressource": "exports",
         "beschreibung": "Nimmt die Excel-Datei des VSA entgegen und gibt sie mit befüllten Eingabezellen zurück; die Datei wird nicht gespeichert.",
         "body": "datei", "formfelder": {"school_id": ("uuid", "Schule", "Planung je Schule"), "school_year_id": ("uuid", "Schuljahr", "Planung je Schuljahr")},
         "antwort": "datei:application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"},
        {"pfad": f"{O}/exports/planning", "methode": "get", "op": "exportPlanning", "summary": "Planung als Excel exportieren", "ressource": "exports",
         "query": [("school_id", "uuid", "Schule", "Planung je Schule"), ("school_year_id", "uuid", "Schuljahr", "Planung je Schuljahr")],
         "antwort": "datei:application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "fehler": ("401", "403", "422")},
    ],
    "ereignisse": {
        "staffing.release.created": ("ReleaseEvent", "Pensum freigegeben (für EduKSX-Flow, EduKSX-Time, Lohn)"),
        "staffing.release.employed": ("ReleaseEvent", "Anstellung erledigt"),
        "staffing.release.changed": ("ReleaseEvent", "Freigegebenes Pensum geändert – Schulverwaltung prüfen"),
    },
}
